// QueryCategories queries the categories edge of a Profile.
func (c *ProfileClient) QueryCategories(_m *Profile) *BusinessCategoryQuery {
	query := (&BusinessCategoryClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(profile.Table, profile.FieldID, id),
			sqlgraph.To(businesscategory.Table, businesscategory.FieldID),
			sqlgraph.Edge(sqlgraph.M2M, false, profile.CategoriesTable, profile.CategoriesPrimaryKey...),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

